async function filesUnder(directory){
  const absoluteDirectory=resolve(projectRoot,directory),e=await readdir(absoluteDirectory,{withFileTypes:true});
  const nested=await Promise.all(e.map(async entry=>{
    const path=relative(projectRoot,resolve(absoluteDirectory,entry.name)).replaceAll('\\','/');
    return entry.isDirectory()?filesUnder(path):[path];
  }));
  return nested.flat();
}
